DIFFICULTIES = [("easy", 8), ("medium", 8), ("hard", 4)]
questions = []
for chapter_id, chapter_title, records in CHAPTERS:
    if len(records) != 20:
        raise ValueError(f"{chapter_title}: expected 20 records, got {len(records)}")
    for index, (difficulty, item) in enumerate(
        (difficulty, record)
        for difficulty, amount in DIFFICULTIES
        for record in records[sum(n for _level, n in DIFFICULTIES[:DIFFICULTIES.index((difficulty, amount))]):sum(n for _level, n in DIFFICULTIES[:DIFFICULTIES.index((difficulty, amount))])+amount]
    ):
        q, answer, distractors, why = item
        options = [answer] + list(distractors)
        if len(options) != 4 or len(set(options)) != 4:
            raise ValueError(f"Invalid options: {chapter_title} / {q}")
        chapter_number = int(chapter_id[-2:])
        questions.append({
            "id": f"C6SCI{chapter_number:02d}-{difficulty[:1].upper()}{index+1:02d}",
            "grade": "Class 6",
            "subject": "Science",
            "chapter_id": chapter_id,
            "topic": "Chapter Practice",
            "concept_id": chapter_id + "-chapter-concepts",
            "concept": chapter_title,
            "prerequisites": [],
            "difficulty": difficulty,
            "q": q,
            "options": options,
            "answer": answer,
            "why": why,
        })

out = {
    "bank_version": "class6-science-1.0",
    "curriculum_version": "NCERT-Curiosity-Class6-2026-27",
    "source_note": "Original practice questions aligned to the NCERT Curiosity Grade 6 chapter themes. These questions are not copied from the textbook and should be reviewed by a science teacher before production use.",
    "source": "https://ncert.nic.in/textbook.php?fecu1=0-12",
    "questions": questions,
}
path = Path(__file__).resolve().parent / "question_banks" / "class6_science.json"
path.parent.mkdir(parents=True, exist_ok=True)
path.write_text(json.dumps(out, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(f"Wrote {len(questions)} questions to {path}")
